const emptyConfig:AgentConfig={baseUrl:'',apiKey:'',model:''};
const record=(v:unknown):v is Record<string,unknown>=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const strings=(v:unknown)=>record(v)&&Object.values(v).every(x=>typeof x==='string');
const textOf=(error:unknown)=>error instanceof Error?error.message:'操作失败，请重试。';
function readSettings(){try{const value=JSON.parse(localStorage.getItem(settingsKey)||'null');return value&&['baseUrl','apiKey','model'].every(k=>typeof value[k]==='string')?value as AgentConfig:{...emptyConfig};}catch{return {...emptyConfig};}}
function readTheme(){try{return localStorage.getItem(themeKey)==='dark'?'dark':'light';}catch{return 'light';}}
function download(name:string,value:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validNode(v:unknown):v is FlowNode{
 if(!record(v)||typeof v.id!=='string'||!v.id||v.type!=='block'||!record(v.position)||!Number.isFinite(v.position.x)||!Number.isFinite(v.position.y)||!record(v.data))return false;
 const d=v.data;if(typeof d.kind!=='string'||!Object.hasOwn(blockMeta,d.kind)||typeof d.label!=='string')return false;
 if(!['description','requestId','method','url','body','variable','value','source','path','operator','expected','template','acceptStatus','generatedKey','groupId','groupLabel','readiness','uncertainty'].every(k=>d[k]===undefined||typeof d[k]==='string'))return false;
 if(d.headers!==undefined&&!strings(d.headers))return false;
 if(!['evidence','inputs','outputs'].every(k=>d[k]===undefined||(Array.isArray(d[k])&&d[k].every(x=>typeof x==='string'))))return false;
 return d.bindings===undefined||(Array.isArray(d.bindings)&&d.bindings.every(b=>record(b)&&['id','name','path'].every(k=>typeof b[k]==='string')&&['body','header','query','url'].includes(String(b.target))&&['fixed','user','upstream','runtime','manual'].includes(String(b.mode))&&['value','source','sourcePath','generator','evidence'].every(k=>b[k]===undefined||typeof b[k]==='string')&&(b.required===undefined||typeof b.required==='boolean')));
}
function validRequest(v:unknown):v is HarRequest{return record(v)&&['id','method','url','domain','path','category','mimeType','body','responseBody'].every(k=>typeof v[k]==='string')&&Number.isFinite(v.status)&&Number.isFinite(v.duration)&&['headers','responseHeaders','query'].every(k=>strings(v[k]));}
function reachable(nodes:FlowNode[],edges:FlowEdge[],entryId:string){const incoming=new Set(edges.map(e=>e.target));const roots=nodes.filter(n=>!incoming.has(n.id)).map(n=>n.id);const start=entryId||((roots.length===1&&roots[0])||'');const ids=new Set<string>();const todo=start?[start]:[];while(todo.length){const id=todo.pop()!;if(ids.has(id))continue;ids.add(id);todo.push(...edges.filter(e=>e.source===id).map(e=>e.target));}return {ids,roots,start};}

