 const [uploadProgress,setUploadProgress]=useState<ImportProgress|null>(null),[uploadFailure,setUploadFailure]=useState<HarImportError|null>(null),[uploadCancelled,setUploadCancelled]=useState(false),[uploadNow,setUploadNow]=useState(Date.now());
