 const [job,setJob]=useState<RunJob|null>(null),[events,setEvents]=useState<RunEvent[]>([]),[result,setResult]=useState<RunResult|null>(null),[fullResult,setFullResult]=useState(false),[resultLoading,setResultLoading]=useState(false),[stepResults,setStepResults]=useState<Record<string,RunResult['steps'][number]>>({}),[loadingStep,setLoadingStep]=useState(false),[headerDrafts,setHeaderDrafts]=useState<Record<string,{text:string;error:string}>>({}),[draftIssues,setDraftIssues]=useState<Record<string,string>>({}),[runError,setRunError]=useState(''),[disconnected,setDisconnected]=useState(false),[now,setNow]=useState(Date.now());
 const fileRef=useRef<HTMLInputElement>(null),projectRef=useRef<HTMLInputElement>(null);
 const uploadRetry=useRef<{file:File;view:ImportView|null}|null>(null),uploadAttempt=useRef(0);
 const analysisAbort=useRef<AbortController|null>(null),runAbort=useRef<AbortController|null>(null),uploadAbort=useRef<AbortController|null>(null),epoch=useRef(0),fileRevision=useRef(0),dataset=useRef<string>(crypto.randomUUID()),suppressed=useRef(new Set<string>()),runMap=useRef<Record<string,string>>({}),jobRef=useRef<RunJob|null>(null);jobRef.current=job;
 const tell=useCallback((message:string,error=false)=>setNotice({message,error}),[]);
