 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(null),6500);return()=>clearTimeout(timer);},[notice]);
 useEffect(()=>()=>{uploadAttempt.current++;if(!uploadAbort.current)void discardHarImport(uploadRetry.current?.view);uploadRetry.current=null;analysisAbort.current?.abort();runAbort.current?.abort();uploadAbort.current?.abort();},[]);
