 const selected=nodes.find(n=>n.id===selectedId);
 const roots=useMemo(()=>reachable(nodes,edges,entryId).roots,[nodes,edges,entryId]);
 const filtered=useMemo(()=>requests.filter(r=>{const time=r.startedDateTime||r.startedAt||'';return(showStatic||r.category!=='static')&&(category==='all'||r.category===category)&&(page==='all'||r.pageId===page)&&(!search||`${r.url} ${r.method} ${r.id}`.toLowerCase().includes(search.toLowerCase()))&&(!fromTime||!!time&&time>=fromTime)&&(!toTime||!!time&&time<=toTime);}),[requests,showStatic,category,page,search,fromTime,toTime]);
 const analyzedBlocks=useMemo(()=>new Map(getHarBlocks(requests,analysis?.suggestions??[]).map(b=>[b.request.id,b])),[requests,analysis]);
 const groups=useMemo(()=>planRequestGroups(filtered),[filtered]);
 const runtime=useMemo(()=>({events:new Map(events.map(e=>[e.nodeId,e])),now}),[events,now]);
 const designGroups=useMemo(()=>{const map=new Map<string,FlowNode[]>();for(const n of nodes)if(n.data.groupId){const list=map.get(n.data.groupId)||[];list.push(n);map.set(n.data.groupId,list);}return map;},[nodes]);
 const view=useMemo(()=>{
  const mapping=new Map<string,string>(),viewNodes:CanvasNode[]=[],groupPositions=new Map<string,{x:number;y:number}>();
  for(const [id,members]of designGroups){if(members.length<2)continue;const open=expanded.has(id);const position=open?{x:Math.min(...members.map(n=>n.position.x)),y:Math.min(...members.map(n=>n.position.y))}:{...members[0].position};groupPositions.set(`view-group:${id}`,position);viewNodes.push({id:`view-group:${id}`,type:'businessGroup',...groupDimensions(groupMeasurements,id,open),position:{x:position.x,y:position.y-(open?95:0)},data:{groupId:id,label:members[0].data.groupLabel||'业务分组',nodeIds:members.map(n=>n.id),names:members.map(n=>n.data.label),expanded:open},draggable:!open,selectable:!open});if(!open)members.forEach(n=>mapping.set(n.id,`view-group:${id}`));}
  for(const n of nodes)if(!mapping.has(n.id))viewNodes.push({...n,selected:n.id===selectedId});
  const viewEdges=edges.flatMap(e=>{const source=mapping.get(e.source)||e.source,target=mapping.get(e.target)||e.target;if(source===target)return [];const active=runtime.events.get(e.target)?.status==='running'&&runtime.events.has(e.source);return [{...e,source,target,type:'smoothstep',animated:active,style:{...e.style,stroke:active?'var(--success)':'var(--edge)'},className:active?'running-edge':''}];});
  return {nodes:viewNodes,edges:viewEdges,groupPositions};
 },[nodes,edges,designGroups,expanded,selectedId,runtime,groupMeasurements]);
 const fit=()=>setTimeout(()=>void flow.fitView({padding:0.18,duration:250}),80);
 const toggleGroup=useCallback((id:string)=>setExpanded(old=>{const next=new Set(old);next.has(id)?next.delete(id):next.add(id);return next;}),[]);
 const locate=useCallback((id:string,field='')=>{const n=graph.current.nodes.find(n=>n.id===id);if(!n)return;if(n.data.groupId)setExpanded(old=>new Set([...old,n.data.groupId!]));setSelectedId(id);setFocusField(field);setRightTab('inspector');setTimeout(()=>{void flow.setCenter(n.position.x+140,n.position.y+110,{zoom:0.9,duration:250});},60);},[flow]);
 const reset=(keepImportId?:string)=>{epoch.current++;fileRevision.current++;uploadAttempt.current++;if(!uploadAbort.current)void discardHarImport(uploadRetry.current?.view,keepImportId);uploadRetry.current=null;setUploadProgress(null);setUploadFailure(null);setUploadCancelled(false);analysisAbort.current?.abort();runAbort.current?.abort();uploadAbort.current?.abort();if(jobRef.current&&['running','waiting_input'].includes(jobRef.current.status))void cancelRunJob(jobRef.current.id).catch(()=>{});dataset.current=crypto.randomUUID();suppressed.current.clear();setGraph({nodes:[],edges:[]});setAnalysis(null);setProgress(null);setPending([]);setLogs([]);setIssues([]);setEvents([]);setJob(null);jobRef.current=null;setResult(null);setFullResult(false);setStepResults({});setDraftIssues({});setHeaderDrafts({});setRunError('');setDisconnected(false);setSelectedId(null);setUndo(null);setExpanded(new Set());setGroupMeasurements(new Map());setValues({});setEntryId('');setParsing(false);setAnalyzing(false);setChecking(false);setResuming(false);setLoadingStep(false);setResultLoading(false);setEdgeMenu(null);};
 const acceptCapture=(data:ParseResult,name:string)=>{setCapture(data);setRequests(data.requests);setFileName(name);setSearch('');setCategory('all');setPage('all');setFromTime('');setToTime('');setLeftTab('groups');tell(`已解析 ${data.requests.length} 条请求。描述目标后点击分析，开始整理业务步骤。`);};
 const upload=async(file:File,resume?:ImportView|null)=>{
  reset(resume?.id);setRequests([]);setCapture(null);setFileName(file.name);setParsing(true);setUploadNow(Date.now());
  const rev=epoch.current,attempt=++uploadAttempt.current,controller=new AbortController();uploadAbort.current=controller;uploadRetry.current={file,view:resume??null};
  const current=()=>rev===epoch.current&&attempt===uploadAttempt.current&&uploadAbort.current===controller;
  try{
   if(file.size>HAR_IMPORT_LIMIT)throw new HarImportError('HAR 文件超过 256 MiB，请缩小抓包范围后重新选择。',{code:'INVALID_FILE_SIZE'});
   const data=await importHar(file,{signal:controller.signal,resume,onProgress:next=>{if(!current()||controller.signal.aborted)return;setUploadProgress(next);setUploadNow(Date.now());uploadRetry.current={file,view:next.view};}});
   if(current()&&!controller.signal.aborted)acceptCapture(data,file.name);
  }catch(error){
   if(current()&&!controller.signal.aborted){const failure=error instanceof HarImportError?error:new HarImportError(textOf(error));if(failure.code==='CANCELLED'){setUploadCancelled(true);uploadRetry.current={file,view:null};}else{if(failure.status===404||failure.status===410)failure.message+=' 导入任务已过期或不存在，重试会重新上传该文件。';setUploadFailure(failure);uploadRetry.current={file,view:failure.status===404||failure.status===410?null:failure.view};tell(failure.message,true);}}
  }finally{if(current()){setParsing(false);uploadAbort.current=null;}}
 };
 const cancelUpload=()=>{if(!parsing)return;uploadAttempt.current++;uploadAbort.current?.abort();uploadAbort.current=null;if(uploadRetry.current)uploadRetry.current={file:uploadRetry.current.file,view:null};setParsing(false);setUploadFailure(null);setUploadCancelled(true);};
 const retryUpload=()=>{const retained=uploadRetry.current;if(retained)void upload(retained.file,uploadCancelled?null:retained.view);};
 const openProject=async(file:File)=>{const revision=++fileRevision.current;try{const value:unknown=JSON.parse(await file.text());if(revision!==fileRevision.current)return;if(!record(value)||!Array.isArray(value.nodes)||!value.nodes.every(validNode)||value.nodes.length>3000||!Array.isArray(value.edges)||value.edges.length>5000)throw new Error('项目文件的节点或连线格式无效。');const ids=new Set(value.nodes.map(n=>n.id));if(ids.size!==value.nodes.length||!value.edges.every(e=>record(e)&&typeof e.id==='string'&&typeof e.source==='string'&&typeof e.target==='string'&&ids.has(e.source)&&ids.has(e.target)&&(e.sourceHandle===undefined||e.sourceHandle===null||typeof e.sourceHandle==='string')))throw new Error('项目存在重复节点或无效连线。');if(value.requests!==undefined&&(!Array.isArray(value.requests)||!value.requests.every(validRequest)))throw new Error('项目中的 HAR 记录格式无效。');reset();setGraph({nodes:value.nodes,edges:value.edges as FlowEdge[]});setRequests((value.requests as HarRequest[])||[]);setFileName(typeof value.fileName==='string'?value.fileName:file.name);setCapture(null);if(typeof value.datasetKey==='string')dataset.current=value.datasetKey;setGoal(typeof value.goal==='string'?value.goal:'');setManualSteps(typeof value.manualSteps==='string'?value.manualSteps:'');tell('项目已打开。运行状态和模型设置由当前工作台管理。');fit();}catch(error){tell(textOf(error),true);}};
 const rememberDelete=(removedNodes:FlowNode[],removedEdges:FlowEdge[])=>{setUndo({nodes:removedNodes,edges:removedEdges,nodeOrder:graph.current.nodes.map(n=>n.id),edgeOrder:graph.current.edges.map(e=>e.id)});for(const n of removedNodes)if(n.data.requestId)suppressed.current.add(n.data.requestId);};
 const removeNodes=(ids:Set<string>,extraEdges=new Set<string>())=>{const current=graph.current;const removedNodes=current.nodes.filter(n=>ids.has(n.id)),removedEdges=current.edges.filter(e=>ids.has(e.source)||ids.has(e.target)||extraEdges.has(e.id));rememberDelete(removedNodes,removedEdges);setGraph({nodes:current.nodes.filter(n=>!ids.has(n.id)).map(n=>ids.has(n.data.source??'')||n.data.bindings?.some(b=>b.mode==='upstream'&&ids.has(b.source??''))?{...n,data:{...n.data,readiness:'missing-input',uncertainty:'来源步骤已删除，请重新选择数据来源并检查连接。'}}:n),edges:current.edges.filter(e=>!removedEdges.some(r=>r.id===e.id))});if(selectedId&&ids.has(selectedId))setSelectedId(null);};
 const deleteEdge=(kind:DeletionKind)=>{if(!edgeMenu)return;const current=graph.current,plan=planGraphDeletion(current.nodes,current.edges,edgeMenu.id,kind);rememberDelete(plan.removedNodes,plan.removedEdges);setGraph({nodes:plan.nodes,edges:plan.edges});setEdgeMenu(null);};
